private static Map<String, String> applyFeatureGate(SubmitApplicationRequest request, Map<String, String> conf) {
    String featureSwitch = "RangerOnCustomImage";
    List<String> rangerKeys = new ArrayList<>(Arrays.asList("spark.sql.extensions", "spark.ranger.plugin.spark.env"));
    Map<String, String> filteredMap = conf.entrySet().stream().filter(map -> {
        if (request.getImage() != null && (StringUtils.isEmpty(conf.get(featureSwitch)) || !conf.get(featureSwitch).equalsIgnoreCase("On"))) {
            return !rangerKeys.contains(map.getKey());
        } else {
            return true;
        }
    }).collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    return filteredMap;
}
